// How many frames the CPU may run ahead of the GPU. Anything sized per
// frame-in-flight -- command buffers, sync objects, the per-frame uniform
// allocator below -- is sized by this.
constexpr int MAX_FRAMES_IN_FLIGHT = 2;

// --- Debug primitive pipelines ---
// One shader pair (debug.vert/.frag) and one layout behind every debug
// primitive. Lines, filled polygons and solid boxes differ in topology,
// blending and depth state -- not in a shader -- so they are three pipelines
// over one program.
static VkPipelineLayout g_debug_pipeline_layout = VK_NULL_HANDLE;
static VkPipeline       g_debug_box_pipeline    = VK_NULL_HANDLE; // triangles, opaque, writes depth
static VkPipeline       g_debug_line_pipeline   = VK_NULL_HANDLE; // lines, dynamic depth bias
static VkPipeline       g_debug_face_pipeline   = VK_NULL_HANDLE; // triangles, alpha, no depth write

// The occluded halves: the same two programs with the depth test INVERTED, so
// they paint exactly the fragments their depth-tested twin rejected. Used for
// the dimmed second draw of an entry flagged debug_line_t::draw_when_occluded.
static VkPipeline g_debug_line_occluded_pipeline = VK_NULL_HANDLE;
static VkPipeline g_debug_face_occluded_pipeline = VK_NULL_HANDLE;

static bool g_supports_wireframe = false;

// --- The mesh pipeline cache ---
//
// Everything a mesh pipeline IS: the material's state, the mesh's vertex layout
// and the draw's fill mode. Nine hand-named pipeline globals and a submit-time
// decision tree collapsed into this one key. That is the point of the rewrite --
// a new axis now adds a field here instead of multiplying branches at draw time.
struct pipeline_key_t
{
  pipeline_state_t state;
  vertex_layout_t  vertex_layout = vertex_layout_t::static_mesh;
  fill_mode_t      fill          = fill_mode_t::solid;

  bool operator==(const pipeline_key_t &) const = default;
};

struct pipeline_key_hash_t
{
  size_t operator()(const pipeline_key_t &key) const
  {
    // Every field is a small enumeration, so the whole key packs into one
    // integer and needs no hash combine.
    return (size_t)key.state.shader | ((size_t)key.state.blend_mode << 2) |
           ((size_t)key.state.cull_mode << 4) | ((size_t)key.state.depth_test << 5) |
           ((size_t)key.state.depth_write << 6) | ((size_t)key.vertex_layout << 7) |
           ((size_t)key.fill << 8);
  }
};

// ONE pipeline layout for every mesh pipeline: set 0 = albedo sampler, set 1 =
// the bone matrices, one 128-byte push range covering both stages. A static
// pipeline simply never binds set 1, which is what let four layouts become one.
static VkPipelineLayout      g_mesh_pipeline_layout = VK_NULL_HANDLE;
static VkDescriptorSetLayout g_albedo_ds_layout     = VK_NULL_HANDLE;
static VkDescriptorPool      g_albedo_pool          = VK_NULL_HANDLE;

// Pipelines are handed around as INDICES rather than VkPipelines so a draw list
// can be sorted on an integer without chasing the map for every comparison.
static std::vector<VkPipeline>                                          g_pipelines;
static std::unordered_map<pipeline_key_t, uint32_t, pipeline_key_hash_t> g_pipeline_ids;

// How many distinct textures can be bound as material albedo. A hard cap rather
// than a growing pool because exhausting it is a content problem worth hearing
// about, not something to paper over by allocating another pool.
constexpr uint32_t MAX_MATERIAL_TEXTURES = 64;

